class WordDictionary {
    private final Map<Integer, List<String>> byLen = new HashMap<>();

    public WordDictionary() {}

    public void addWord(String word) {
        byLen.computeIfAbsent(word.length(), k -> new ArrayList<>()).add(word);
    }

    public boolean search(String word) {
        List<String> candidates = byLen.get(word.length());
        if (candidates == null) return false;
        for (String w : candidates) {
            if (matches(word, w)) return true;
        }
        return false;
    }

    private boolean matches(String pattern, String w) {
        for (int i = 0; i < pattern.length(); i++) {
            char p = pattern.charAt(i);
            if (p != '.' && p != w.charAt(i)) return false;
        }
        return true;
    }
}

